<!-- This file is generated by AI. -->

<!--
  设置。分类固定为「编辑器 / 引擎 / 模板 / 关于」, 因此可以直接定位到某一类 (例如从"新建项目"
  里点"去添加引擎"直达"引擎")。这里只承载表单; 每一项的语义见 `lib/settings.ts`。
-->

<script lang="ts">
  import { getVersion } from '@tauri-apps/api/app';
  import { openUrl } from '@tauri-apps/plugin-opener';
  import { onMount } from 'svelte';

  import type { IconName } from './icons';
  import { appStore, actions, type SettingsCategory } from '../state/store.svelte';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Checkbox from './Checkbox.svelte';
  import EngineTemplateManager from './EngineTemplateManager.svelte';
  import Icon from './Icon.svelte';
  import Input from './Input.svelte';
  import Select from './Select.svelte';

  const settings = $derived(appStore.settings);

  /**
   * 应用版本, 向 Tauri 要 (`tauri.conf.json` 的 `version` 是唯一权威): 硬编码的字符串发版时
   * 没人会记得回来改。读不到 (例如跑在纯浏览器里) 就整行不渲染, 而不是显示一个假的默认值。
   */
  let version = $state('');

  onMount(() => {
    void getVersion()
      .then((value) => (version = value))
      .catch(() => {});
  });

  const CATEGORIES: { id: SettingsCategory; label: string }[] = [
    { id: 'editor', label: '编辑器' },
    { id: 'engine', label: '引擎' },
    { id: 'template', label: '模板' },
    { id: 'about', label: '关于' },
  ];

  /** 「关于」页的外部链接。 */
  const ABOUT_LINKS: { label: string; iconName: IconName; url: string }[] = [
    { label: '仓库：WebGAL LSP', iconName: 'Globe', url: 'https://github.com/fltLi/webgal-lsp' },
    { label: '许可：MPL-2.0', iconName: 'Document', url: 'https://www.mozilla.org/MPL/2.0/' },
  ];

  const DIAGNOSTICS_OPTIONS = [
    { value: 'dock', label: '底部托盘' },
    { value: 'modal', label: '弹窗' },
  ];

  const GIT_DIFF_OPTIONS = [
    { value: 'sideBySide', label: '并排' },
    { value: 'inline', label: '内联' },
  ];

  function close() {
    actions.setSettingsOpen(false);
  }

  function patch(part: Parameters<typeof actions.updateSettings>[0]) {
    actions.updateSettings(part);
  }

  /*
   * 字体与字号用本地草稿而不是直接绑到 store: 直接绑会把用户**每一个按键**都写进 localStorage
   * (设置每次变更都会落盘), 而且字号在输入中间态是空串 / 非法值 —— 草稿 + 提交时校验才是干净的。
   *
   * 草稿要用 `$effect` 跟随, 以便设置被外部改动时重新同步 (例如引擎页写入)。
   */
  let fontFamilyDraft = $state('');
  let fontSizeDraft = $state('');

  $effect(() => {
    fontFamilyDraft = settings.editorFontFamily;
    fontSizeDraft = String(settings.editorFontSize);
  });

  function applyFontSize() {
    const size = Number(fontSizeDraft);
    if (!Number.isFinite(size) || size < 8 || size > 32) return;
    patch({ editorFontSize: Math.round(size) });
  }
</script>

{#if appStore.settingsOpen}
  <AppDialog title="设置" iconName="Settings" size="medium" height={560} flush onClose={close}>
    <div class="settings-layout">
      <nav class="settings-nav" aria-label="设置分类">
        {#each CATEGORIES as category (category.id)}
          <button
            type="button"
            class="settings-nav-item"
            class:active={appStore.settingsCategory === category.id}
            onclick={() => actions.setSettingsCategory(category.id)}
          >
            {category.label}
          </button>
        {/each}
      </nav>

      <div class="settings-content">
        {#if appStore.settingsCategory === 'editor'}
          <!--
            「主题」没有单独一组: 标题栏那个按钮就是主题开关, 再占一组反而重复。
            它是**三态循环** (浅色 → 深色 → 跟随系统, 见 `ui/TitleBar.svelte`), 因此"跟随系统"
            不需要额外的入口。
          -->
          <section class="settings-group">
            <h3>编辑器</h3>
            <div class="settings-field">
              <span class="settings-label">字体</span>
              <Input bind:value={fontFamilyDraft} oninput={() => patch({ editorFontFamily: fontFamilyDraft })} />
            </div>
            <div class="settings-field">
              <span class="settings-label">字号</span>
              <Input type="number" bind:value={fontSizeDraft} oninput={() => applyFontSize()} />
            </div>
            <Checkbox
              checked={settings.editorWordWrap}
              label="自动换行"
              onchange={(checked) => patch({ editorWordWrap: checked })}
            />
            <Checkbox
              checked={settings.editorMinimap}
              label="显示缩略图"
              onchange={(checked) => patch({ editorMinimap: checked })}
            />
          </section>

          <section class="settings-group">
            <!--
              这里**刻意没有**「光标移动时同步预览」: 预览引擎常驻接入, 那个开关只决定"画面是否跟着
              光标走", 属于边写边调的高频动作, 入口只在预览工具条上 (见 `PreviewPanel.svelte`)。
              设置里再放一份会让它看起来像"预览总开关"。
            -->
            <h3>保存与界面</h3>
            <Checkbox
              checked={settings.autoSave}
              label="自动保存"
              onchange={(checked) => patch({ autoSave: checked })}
            />
            <div class="settings-field">
              <span class="settings-label">诊断列表</span>
              <Select
                value={settings.diagnosticsView}
                options={DIAGNOSTICS_OPTIONS}
                title="诊断列表以弹窗还是底部托盘打开"
                onchange={(next) => patch({ diagnosticsView: next as typeof settings.diagnosticsView })}
              />
            </div>
            <div class="settings-field">
              <span class="settings-label">Git 差异</span>
              <Select
                value={settings.gitDiffView}
                options={GIT_DIFF_OPTIONS}
                title="Git 差异选项卡内联还是并排显示"
                onchange={(next) => patch({ gitDiffView: next as typeof settings.gitDiffView })}
              />
            </div>
          </section>
        {:else if appStore.settingsCategory === 'about'}
          <section class="settings-group">
            <h3>关于</h3>
            <div class="settings-about">
              <section class="settings-about-intro">
                <img class="settings-about-mark" src="icon.svg" alt="" draggable="false" />
                <div>
                  <div class="settings-about-title-row">
                    <h3 class="settings-about-title">WebGAL Ink</h3>
                    {#if version}
                      <span class="settings-about-version">v{version}</span>
                    {/if}
                  </div>
                  <p class="settings-about-description">WebGAL 视觉小说代码编辑器</p>
                </div>
              </section>

              <!-- 链接列表用 styles.css 里既有的 `.settings-link-*` 规则; 版本号向 Tauri 要 (见脚本里) -->
              <section class="settings-about-section">
                <div class="settings-about-section-head">
                  <h4>资源与支持</h4>
                </div>
                <div class="settings-link-list">
                  {#each ABOUT_LINKS as link (link.url)}
                    <button type="button" class="settings-link-item" onclick={() => void openUrl(link.url)}>
                      <span class="settings-link-icon"><Icon name={link.iconName} size={16} /></span>
                      <span class="settings-link-copy">
                        <span>{link.label}</span>
                        <small>{link.url.replace('https://', '')}</small>
                      </span>
                    </button>
                  {/each}
                </div>
              </section>

              <footer class="settings-about-footer">
                <span>© 2026 fltLi</span>
                <span>MPL-2.0</span>
              </footer>
            </div>
          </section>
        {:else}
          <!-- 引擎 / 模板**内联**管理: 换成子对话框会多一层壳、少一屏信息 -->
          <EngineTemplateManager kind={appStore.settingsCategory === 'engine' ? 'engine' : 'template'} />
        {/if}
      </div>
    </div>

    <!-- 底部操作栏: 与仓库里其它对话框一样, "关闭"永远在同一个位置 -->
    {#snippet footer()}
      <Button appearance="primary" onclick={close}>关闭</Button>
    {/snippet}
  </AppDialog>
{/if}
